            bool hasExpected = !string.IsNullOrWhiteSpace(test.Intent); bool currentPass = hasExpected && ParserComparisonService.Matches(test.Intent, test.Targets, test.Status, test.Keyword, test.Reference, test.Title, current); bool semantic = hasExpected && response.SchemaSuccess && ParserComparisonService.Matches(test.Intent, test.Targets, test.Status, test.Keyword, test.Reference, test.Title, response.Result);
