        private void Show(ParserComparisonRecord record) { CurrentResult = record.CurrentParserResult.Display; GraniteResult = record.GraniteRawResponse ?? record.Metrics.Error; HybridResult = record.HybridResult.Source + " · " + (record.HybridResult.Result == null ? "NEEDS_CLARIFICATION" : record.HybridResult.Result.Intent + " [" + string.Join(",", record.HybridResult.Result.TargetIndexes) + "] " + (record.HybridResult.Result.Status ?? "null")) + " · Fallback " + (record.HybridResult.FallbackCalled ? "YES" : "NO") + " · " + Pass(record.HybridPass); DecisionReason = record.HybridResult.Reason; Metrics = "ColdStart " + record.Metrics.ColdStart + " · " + record.Metrics.LatencyMs + " ms · JSON " + Pass(record.JsonPass) + " · Schema " + Pass(record.SchemaPass) + " · Slave RAM " + record.Metrics.ProcessWorkingSetMB + " MB · Ollama RAM " + record.Metrics.OllamaWorkingSetMB + " MB · Model " + record.Metrics.ModelMemoryMB + " MB (VRAM " + record.Metrics.ModelVramMB + " MB)"; }
        private async Task RunSuiteAsync()
