                List<ParserComparisonRecord> warm = records.Where(x => !x.Metrics.ColdStart).ToList(); ParserComparisonRecord cold = records.FirstOrDefault(x => x.Metrics.ColdStart); bool path = records.All(x => x.BenchmarkPathMatch); Summary = "AI Test Summary\nCurrent Parser Accuracy: " + Rate(records.Count(x => x.CurrentParserPass), records.Count) + "\nQwen Semantic Accuracy: " + Rate(records.Count(x => x.SemanticPass), records.Count) + "\nQwen Schema Success: " + Rate(records.Count(x => x.SchemaPass), records.Count) + "\nQwen Final Accuracy: " + Rate(records.Count(x => x.FinalPass), records.Count) + "\nBenchmark Path Match: " + (path ? "PASS" : "BENCHMARK_PATH_MISMATCH") + "\nCold Start Latency: " + (cold == null ? "N/A" : cold.Metrics.LatencyMs + " ms") + "\nWarm Average Latency: " + (warm.Count == 0 ? "N/A" : warm.Average(x => x.Metrics.LatencyMs).ToString("0") + " ms") + "\nMin / Max: " + records.Min(x => x.Metrics.LatencyMs) + " / " + records.Max(x => x.Metrics.LatencyMs) + " ms\nSlave RAM: " + records.Max(x => x.Metrics.ProcessWorkingSetMB) + " MB\nOllama RAM: " + records.Max(x => x.Metrics.OllamaWorkingSetMB) + " MB\nModel Memory / VRAM: " + records.Max(x => x.Metrics.ModelMemoryMB) + " / " + records.Max(x => x.Metrics.ModelVramMB) + " MB"; HybridSummary = BuildHybridSummary(records); StatusText = suite.Count + "건 상세 Benchmark 완료 · Task/GitHub 실행 0건";
