        private IList<WorkTask> CandidateTasks() { List<WorkTask> values = new List<WorkTask>(); string[] lines = (Context ?? "").Split(new[] { '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries); foreach (string line in lines) { string text = System.Text.RegularExpressions.Regex.Replace(line, @"^\s*\d+\.\s*", ""); string[] parts = text.Split(new[] { " - " }, StringSplitOptions.None); WorkTaskStatus status; if (!Enum.TryParse(parts.Length > 1 ? parts[parts.Length - 1].Replace(" ", "") : "Todo", true, out status)) status = WorkTaskStatus.Todo; values.Add(new WorkTask { Id = Guid.NewGuid(), Title = parts[0].Trim(), Status = status, CreatedAt = DateTime.Now, UpdatedAt = DateTime.Now }); } return values; }
        private static string Pass(bool value) { return value ? "PASS" : "FAIL"; } private static string Rate(int count, int total) { return total == 0 ? "0%" : (count * 100d / total).ToString("0.0") + "%"; }
        private static string BuildHybridSummary(IList<ParserComparisonRecord> records)
        {
            int both = records.Count(x => x.CurrentParserPass && x.FinalPass), parserOnly = records.Count(x => x.CurrentParserPass && !x.FinalPass), llmOnly = records.Count(x => !x.CurrentParserPass && x.FinalPass), neither = records.Count(x => !x.CurrentParserPass && !x.FinalPass), covered = records.Count(x => x.CurrentParserPass || x.FinalPass);
            int fallback = records.Count(x => x.HybridResult.FallbackCalled), fallbackSuccess = records.Count(x => x.HybridResult.FallbackCalled && x.HybridPass), unresolved = records.Count(x => x.HybridResult.Source == HybridCommandSource.UNRESOLVED), multi = records.Count(x => x.HybridResult.MultiActionSchemaLimit);
            StringBuilder text = new StringBuilder("Task-021 Hybrid Summary\nParser Accuracy: ").Append(Rate(records.Count(x => x.CurrentParserPass), records.Count)).Append("\nLLM Accuracy: ").Append(Rate(records.Count(x => x.FinalPass), records.Count)).Append("\nHybrid Accuracy: ").Append(Rate(records.Count(x => x.HybridPass), records.Count)).Append("\nOracle Hybrid Coverage: ").Append(Rate(covered, records.Count)).Append("\nParser Only: ").Append(records.Count - fallback).Append("\nLLM Fallback: ").Append(fallback).Append("\nFallback Success / Failure: ").Append(fallbackSuccess).Append(" / ").Append(fallback - fallbackSuccess).Append("\nUnresolved: ").Append(unresolved).Append("\nParser Avg Latency: ").Append(records.Average(x => x.HybridResult.ParserLatencyMs).ToString("0")).Append(" ms\nLLM Fallback Avg Latency: ").Append(fallback == 0 ? "N/A" : records.Where(x => x.HybridResult.FallbackCalled).Average(x => x.HybridResult.LlmResponse.LatencyMs).ToString("0") + " ms").Append("\nHybrid Avg Latency: ").Append(records.Average(x => x.HybridResult.HybridLatencyMs).ToString("0")).Append(" ms\nMulti Action Schema Limit: ").Append(multi).Append("\n\nHybrid Cross Analysis\nParser O / LLM O : ").Append(both).Append("\nParser O / LLM X : ").Append(parserOnly).Append("\nParser X / LLM O : ").Append(llmOnly).Append("\nParser X / LLM X : ").Append(neither);
            AppendGroup(text, "C. Parser X / LLM O — LLM 보완 문장", records.Where(x => !x.CurrentParserPass && x.FinalPass)); AppendGroup(text, "D. Parser X / LLM X — 미해결 문장", records.Where(x => !x.CurrentParserPass && !x.FinalPass)); return text.ToString();
        }
        private static void AppendGroup(StringBuilder text, string title, IEnumerable<ParserComparisonRecord> values) { text.Append("\n\n").Append(title); foreach (ParserComparisonRecord item in values) text.Append("\n").Append(item.No).Append(". ").Append(item.Input).Append(" | Expected ").Append(item.ExpectedIntent).Append(" ").Append("[").Append(string.Join(",", item.ExpectedTargets)).Append("] ").Append(item.ExpectedStatus ?? "null").Append(" | Parser ").Append(item.CurrentParserResult.Intent).Append(" [").Append(string.Join(",", item.CurrentParserResult.TargetIndexes)).Append("] ").Append(item.CurrentParserResult.Status ?? "null").Append(" | LLM ").Append(item.GraniteResult == null ? "SCHEMA/JSON FAIL" : item.GraniteResult.Intent + " [" + string.Join(",", item.GraniteResult.TargetIndexes) + "] " + (item.GraniteResult.Status ?? "null")); }
