        private static TestCase T(string i,string intent,int[] targets=null,string status=null,string keyword=null,string reference=null,string title=null) { return new TestCase { Input=i,Intent=intent,Targets=targets??new int[0],Status=status,Keyword=keyword,Reference=reference,Title=title }; } private sealed class TestCase { public string Input; public string Intent; public IList<int> Targets=new List<int>(); public string Status; public string Keyword; public string Reference; public string Title; }
