        private static string Join(IEnumerable<int> x){return "["+string.Join(",",x??new int[0])+"]";} private static string Flag(bool x){return x?"PASS":"FAIL";} private static string Compact(string intent,IEnumerable<int> targets,string status){return (intent??"UNKNOWN")+" "+Join(targets)+" "+(status??"null");}
